using LocalPro.Web.Data;using LocalPro.Web.Domain;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;[Authorize(Roles="Admin")]public class DispatchModel(AppDbContext db,RequestService service):PageModel{public List<ServiceRequest> Items{get;set;}=[];public List<Domain.Professional> Professionals{get;set;}=[];public List<Category> Categories{get;set;}=[];public async Task OnGetAsync(){Items=await service.Query.OrderByDescending(r=>r.CreatedUtc).Take(200).ToListAsync();Professionals=await db.Professionals.Where(p=>p.Approved&&p.AcceptingRequests).ToListAsync();Categories=await db.Categories.Where(c=>c.Active).OrderBy(c=>c.SortOrder).ToListAsync();}public async Task<IActionResult> OnPostAsync(int id,string action,int? professionalId){try{await service.Change(User,id,action,professionalId);}catch(RuleException ex){TempData["Error"]=ex.Message;}return RedirectToPage();}public async Task<IActionResult> OnPostFeeAsync(int category,decimal? fee){if(!ModelState.IsValid||fee<0||fee>10000){TempData["Error"]="Geli qiime sax ah (0–10000).";return RedirectToPage();}var c=await db.Categories.FindAsync(category);if(c==null)return NotFound();c.VisitFee=fee;db.AuditEvents.Add(new(){ActorId=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value,Action=$"Category {category} visit fee changed"});await db.SaveChangesAsync();return RedirectToPage();}}
